const { code, language, framework, testTypes, coverageTarget, existingTests, model } = $json.body;

const lang = language || 'typescript';
const fw = framework || (lang === 'python' ? 'pytest' : 'vitest');
const types = testTypes || ['unit', 'integration', 'edge'];

const typePrompts = {
  unit: 'Unit tests for individual functions/classes with mocked dependencies',
  integration: 'Integration tests for module interactions and API contracts',
  edge: 'Edge case tests: empty inputs, boundary values, malformed data, concurrency',
  property: 'Property-based tests using fast-check / hypothesis',
  mutation: 'Mutation test scenarios to verify test quality',
  contract: 'Contract tests for API schemas and message formats',
  snapshot: 'Snapshot tests for UI components and serialized output',
  performance: 'Benchmark tests with thresholds',
  security: 'Security-focused tests: injection, auth bypass, data exposure'
};

const selectedTypes = types.map(t => typePrompts[t] || `Custom: ${t}`).join('\n');

const systemPrompt = `You are a Senior Test Engineer. Generate production-quality ${fw} tests for ${lang}.

Code under test:
\`\`\`${lang}
${code}
\`\`\`

Existing tests (if any):
\`\`\`${lang}
${existingTests || 'None'}
\`\`\`

Test types to generate:
${selectedTypes}

Coverage target: ${coverageTarget || '80%'}%

Requirements:
1. **AAA Pattern** - Arrange, Act, Assert clearly separated
2. **Descriptive names** - test('should [expected] when [condition]')
3. **Proper mocking** - vi.mock/jest.mock for externals, no real I/O
4. **Type safety** - Full TypeScript types, no 'any'
5. **Isolation** - Each test independent, no shared state
6. **Determinism** - No flaky patterns (timers, random, network)
7. **Edge coverage** - Null, undefined, empty, max, Unicode, concurrent
8. **Error paths** - Exceptions, rejections, timeouts, partial failures
9. **Maintainability** - DRY with helpers, but not over-abstracted
10. **Documentation** - Comments for non-obvious assertions

Output: Complete test file(s) ready to run. Include imports, setup, teardown.`;

return [{ json: {
  systemPrompt,
  userPrompt: `Generate ${types.join(', ')} tests for the provided code`,
  model: model || 'nvidia/nemotron-3-ultra-550b-a55b',
  temperature: 0.1,
  maxTokens: 6000,
  language: lang,
  framework: fw
} }];

const response = $json.choices[0].message.content;
const { language, framework } = $json.body;

const codeBlocks = response.match(/```[\s\S]*?```/g) || [];
const testCode = codeBlocks
  .map(b => b.replace(/^```\w*\n/, '').replace(/\n```$/, ''))
  .join('\n\n');

const ext = language === 'python' ? 'py' : language === 'javascript' ? 'js' : 'ts';
const testExt = framework === 'pytest' ? 'py' : 'test.ts';
const filename = `generated_tests_${Date.now()}.${testExt}`;

return [{ json: {
  success: true,
  testCode,
  fullResponse: response,
  filename,
  language,
  framework,
  model: $json.model,
  usage: $json.usage
} }];

const fs = require('fs');
const path = require('path');

const { testCode, filename } = $json;
const savePath = path.join('/tmp/n8n-tests', filename);

if (!fs.existsSync(path.dirname(savePath))) {
  fs.mkdirSync(path.dirname(savePath), { recursive: true });
}

fs.writeFileSync(savePath, testCode);

return [{ json: { success: true, filePath: savePath, filename } }];

const { testPath, projectPath, framework, coverage, watch, bail, reporter } = $json.body;

const fw = framework || 'vitest';
const cmd = fw === 'pytest'
  ? `python -m pytest ${testPath || ''} ${coverage ? '--cov=.' : ''} ${watch ? '' : ''} ${bail ? '-x' : ''} -v --tb=short`
  : fw === 'jest'
  ? `npx jest ${testPath || ''} ${coverage ? '--coverage' : ''} ${watch ? '--watch' : ''} ${bail ? '--bail' : ''} --verbose`
  : `npx vitest run ${testPath || ''} ${coverage ? '--coverage' : ''} ${bail ? '--run' : ''} --reporter=${reporter || 'verbose'}`;

return [{ json: { command: cmd, projectPath: projectPath || process.cwd(), framework: fw } }];

const { stdout, stderr, exitCode } = $json;

const parseOutput = (output, framework) => {
  const results = {
    passed: 0,
    failed: 0,
    skipped: 0,
    total: 0,
    duration: 0,
    tests: []
  };

  if (!output) return results;

  if (framework === 'pytest') {
    const passedMatch = output.match(/(\d+)\s+passed/);
    const failedMatch = output.match(/(\d+)\s+failed/);
    const skippedMatch = output.match(/(\d+)\s+skipped/);
    const timeMatch = output.match(/in\s+([\d.]+)s/);

    results.passed = passedMatch ? parseInt(passedMatch[1]) : 0;
    results.failed = failedMatch ? parseInt(failedMatch[1]) : 0;
    results.skipped = skippedMatch ? parseInt(skippedMatch[1]) : 0;
    results.total = results.passed + results.failed + results.skipped;
    results.duration = timeMatch ? parseFloat(timeMatch[1]) : 0;
  } else {
    // Vitest / Jest
    const testMatch = output.match(/Tests\s+([\d\w\s,]+)/);
    const passedMatch = output.match(/(\d+)\s+passed/);
    const failedMatch = output.match(/(\d+)\s+failed/);
    const timeMatch = output.match(/Duration\s+([\d.]+)s/) || output.match(/Time:\s+([\d.]+)s/);

    results.passed = passedMatch ? parseInt(passedMatch[1]) : 0;
    results.failed = failedMatch ? parseInt(failedMatch[1]) : 0;
    results.total = results.passed + results.failed;
    results.duration = timeMatch ? parseFloat(timeMatch[1]) : 0;
  }

  return results;
};

const results = parseOutput(stdout, $json.framework);

return [{ json: {
  success: exitCode === 0,
  exitCode,
  summary: `${results.passed} passed, ${results.failed} failed of ${results.total} total (${results.duration}s)`,
  stdout: stdout.substring(0, 5000),
  stderr: stderr.substring(0, 5000),
  results,
  timestamp: new Date().toISOString()
} }];

const { projectPath, framework, include, exclude, threshold } = $json.body;

const fw = framework || 'vitest';
const cmd = fw === 'pytest'
  ? `python -m pytest --cov=. ${include ? `-k "${include}"` : ''} ${exclude ? `--ignore=${exclude}` : ''} --cov-report=json --cov-report=term-missing -q`
  : `npx vitest run --coverage ${include || ''} --reporter=json --outputFile=/tmp/coverage.json`;

return [{ json: { command: cmd, projectPath: projectPath || process.cwd(), framework: fw } }];

const { stdout, stderr, exitCode, framework } = $json;
const fs = require('fs');

let coverage = null;

if (framework === 'vitest' && fs.existsSync('/tmp/coverage.json')) {
  try {
    coverage = JSON.parse(fs.readFileSync('/tmp/coverage.json', 'utf-8'));
  } catch (e) {
    // Fall back to stdout parsing
  }
}

const parseCoverageSummary = (output, fw) => {
  const match = output.match(/All files\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)/);
  if (match) {
    return {
      lines: parseFloat(match[1]),
      branches: parseFloat(match[2]),
      functions: parseFloat(match[3]),
      statements: parseFloat(match[4])
    };
  }
  return null;
};

const summary = parseCoverageSummary(stdout, framework);

return [{ json: {
  success: exitCode === 0,
  coverage,
  summary: summary || parseCoverageSummary(stdout, framework),
  rawOutput: stdout.substring(0, 5000),
  timestamp: new Date().toISOString()
} }];

const { coverage, summary, framework } = $json;

let analysis = '';

if (coverage) {
  const total = coverage.total || {};
  analysis = `## Coverage Summary\n\n`;
  analysis += `- **Lines**: ${total.lines?.pct || 'N/A'}% (${total.lines?.covered || 0}/${total.lines?.total || 0})\n`;
  analysis += `- **Functions**: ${total.functions?.pct || 'N/A'}% (${total.functions?.covered || 0}/${total.functions?.total || 0})\n`;
  analysis += `- **Branches**: ${total.branches?.pct || 'N/A'}% (${total.branches?.covered || 0}/${total.branches?.total || 0})\n`;
  analysis += `- **Statements**: ${total.statements?.pct || 'N/A'}% (${total.statements?.covered || 0}/${total.statements?.total || 0})\n\n`;

  if (coverage.files) {
    analysis += '## Per-File Coverage\n\n';
    analysis += '| File | Lines % | Functions % | Branches % |\n';
    analysis += '|------|---------|-------------|------------|\n';

    Object.entries(coverage.files).forEach(([file, data]) => {
      analysis += `| ${file} | ${data.lines?.pct || 0}% | ${data.functions?.pct || 0}% | ${data.branches?.pct || 0}% |\n`;
    });
    analysis += '\n';
  }

  const uncoveredFiles = coverage.files ? 
    Object.entries(coverage.files)
      .filter(([, data]) => (data.lines?.pct || 100) < 80)
      .sort((a, b) => (a[1].lines?.pct || 100) - (b[1].lines?.pct || 100))
      .slice(0, 10) : [];

  if (uncoveredFiles.length > 0) {
    analysis += '## ⚠️ Files Below 80% Coverage\n\n';
    uncoveredFiles.forEach(([file, data]) => {
      analysis += `- **${file}**: ${data.lines?.pct || 0}% lines\n`;
      if (data.uncoveredLines?.length) {
        analysis += `  - Uncovered lines: ${data.uncoveredLines.slice(0, 10).join(', ')}${data.uncoveredLines.length > 10 ? '...' : ''}\n`;
      }
    });
  }
} else {
  analysis = `## Coverage Output\n\n\`\`\`\n${summary}\n\`\`\``;
}

return [{ json: { success: true, analysis, coverage, timestamp: new Date().toISOString() } }];

const { code, language, framework, bugDescription, stackTrace, model } = $json.body;

const systemPrompt = `You are an Expert Debugger. Given a test failure, identify the root cause and provide a fix.

Language: ${language || 'typescript'}
Framework: ${framework || 'vitest'}

Failing Code:
\`\`\`${language || 'typescript'}
${code}
\`\`\`

Bug Description:
${bugDescription || 'Test failure'}

Stack Trace / Error Output:
\`\`\`
${stackTrace || 'No trace provided'}
\`\`\`

Provide:
1. **Root Cause** - Exactly why the test failed
2. **Minimal Reproduction** - Smallest test case that reproduces the issue
3. **The Fix** - Corrected code with explanation
4. **Regression Prevention** - How to prevent similar bugs in the future`;

return [{ json: {
  systemPrompt,
  userPrompt: 'Analyze test failure and fix',
  model: model || 'nvidia/nemotron-3-ultra-550b-a55b',
  temperature: 0.1,
  maxTokens: 4000
} }];

const { testFiles, projectPath, framework, model } = $json.body;

const systemPrompt = `You are a Test Quality Analyst. Review these test files for:

Test Files:
${testFiles.map(f => `\`\`\`${f.language}\n${f.content}\n\`\`\``).join('\n\n')}

Framework: ${framework || 'vitest'}

Evaluate:
1. **Test Quality** - Are assertions meaningful? No tautologies?
2. **Coverage Gaps** - What's not tested that should be?
3. **Flakiness Risks** - Timers, randomness, shared state, network
4. **Maintainability** - Clear names, DRY, readable, documented
5. **Best Practices** - AAA, proper mocking, isolation, speed
6. **Anti-patterns** - Testing implementation, over-mocking, brittle selectors

Provide specific feedback with line references and improved versions.`;

return [{ json: {
  systemPrompt,
  userPrompt: 'Review test quality',
  model: model || 'nvidia/nemotron-3-ultra-550b-a55b',
  temperature: 0.1,
  maxTokens: 5000
} }];
